import java.util.*;
import java.util.concurrent.*;
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in);int size=s.nextInt(),n=s.nextInt();List<String> words=new ArrayList<>();for(int i=0;i<n;i++)words.add(s.next());try(ExecutorService pool=Executors.newFixedThreadPool(size)){List<Callable<Integer>> tasks=new ArrayList<>();for(String w:words)tasks.add(w::length);int total=0;for(Future<Integer> f:pool.invokeAll(tasks))total+=f.get();System.out.println(total);} } }

