import java.util.concurrent.*;
public class Main {public static void main(String[] args)throws Exception{Scanner s=new Scanner(System.in);int n=s.nextInt();ExecutorService pool=Executors.newFixedThreadPool(2);List<Future<Integer>> fs=new ArrayList<>();for(int i=0;i<n;i++){int v=s.nextInt();fs.add(pool.submit(()->v>0?v:0));}int sum=0;for(Future<Integer> f:fs)sum+=f.get();pool.shutdown();System.out.println(sum);}}
